/**
 * Generador de PDF REAL para el informe de UNA sesión — app móvil (APK).
 *
 * DIFERENCIA HISTÓRICA (ya resuelta aquí): en el APK el WebView de Android
 * NO tiene servidor Python/reportlab, y window.print() del WebView es un
 * no-op silencioso. Antes "Descargar PDF" compartía un HTML imprimible
 * (print-view). Ahora generamos el PDF en el CLIENTE con jsPDF +
 * jspdf-autotable, replicando el diseño del PDF de escritorio
 * (porcipeso/api/reports.py):
 *
 *   · banda de marca verde Eleia (#76B82A) con lockup "PorciPeso · una
 *     solución ELEIA" + logo (data-uri) o wordmark tipográfico,
 *   · chip del lote + fechas de entrada/salida,
 *   · tarjetas de totales (cerdos / kg / promedio),
 *   · tabla de estadística y tabla de movimientos (header verde texto
 *     blanco, zebra, números a la derecha, tipos en español),
 *   · callout "en cristiano",
 *   · aviso DEMO si es_demo,
 *   · pie con lockup/versión/fecha + "Página X de Y".
 *
 * La marca y las traducciones vienen de reportview.ts (misma fuente que el
 * print-view y el CSV) para no tener strings sueltos ni drift.
 *
 * ESTRATEGIA DE PÁGINAS: primero se vuelca TODO el contenido (dejando libre
 * la franja superior donde irá la banda y la inferior del pie); al final,
 * en una sola pasada, se pintan las bandas (portada en pág. 1, slim en las
 * siguientes) y el pie con "Página X de Y". Así las tablas largas que
 * saltan de página quedan bien y no hay hooks frágiles por página.
 */
import { jsPDF } from "jspdf";
import autoTableDefault from "jspdf-autotable";
import type { UserOptions } from "jspdf-autotable";

import { BRAND, cap, fecha, fmt, horaMs, notaHumana, TIPO_HUMANO } from "./reportview";

// jspdf-autotable exporta la función como `default`. Bajo el bundler
// (esbuild) el import default YA es la función; bajo el loader ESM de Node
// (tests/preview) el default es el namespace CJS y la función vive en
// `.default`. Normalizamos para que funcione en ambos.
type AutoTableFn = (doc: jsPDF, options: UserOptions) => void;
const autoTable: AutoTableFn =
  (autoTableDefault as unknown as { default?: AutoTableFn }).default ??
  (autoTableDefault as unknown as AutoTableFn);

type Dict = Record<string, unknown>;
type RGB = [number, number, number];

// ---------------------------------------------------------------- colores

/** hex "#RRGGBB" → [r,g,b] para las APIs de color de jsPDF. */
function rgb(hex: string): RGB {
  const h = hex.replace("#", "");
  return [
    parseInt(h.slice(0, 2), 16),
    parseInt(h.slice(2, 4), 16),
    parseInt(h.slice(4, 6), 16),
  ];
}

const C = {
  green: rgb(BRAND.ELEIA_GREEN),
  greenDark: rgb(BRAND.ELEIA_GREEN_DARK),
  charcoal: rgb(BRAND.ELEIA_CHARCOAL),
  porci: rgb(BRAND.PORCIPESO_GREEN),
  cardBg: rgb(BRAND.CARD_BG),
  cardBorder: rgb(BRAND.CARD_BORDER),
  noteBg: rgb(BRAND.NOTE_BG),
  zebra: rgb(BRAND.ZEBRA),
  border: rgb(BRAND.BORDER),
  white: [255, 255, 255] as RGB,
  bandText: rgb("#EAF5DA"), // verde claro sobre la banda
  demo: rgb("#B45309"), // ámbar del aviso DEMO
};

// ---------------------------------------------------------- geometría (mm)

const PAGE_W = 210;
const PAGE_H = 297;
const MARGIN = 17;
const CONTENT_W = PAGE_W - 2 * MARGIN;
const BAND_FIRST_H = 36;
const BAND_LATER_H = 11;
const FOOTER_H = 20.5; // zona inferior reservada al pie
const CONTENT_TOP_FIRST = BAND_FIRST_H + 5.5;
const CONTENT_TOP_LATER = BAND_LATER_H + 5;
const CONTENT_BOTTOM = PAGE_H - FOOTER_H; // el contenido no baja de aquí

// ------------------------------------------------------------------ marca

// El logo Eleia como data-uri PNG (derivado de
// porcipeso/branding/assets/eleia-logo.png, reescalado para el bundle). Si
// queda vacío, el informe cae al wordmark tipográfico "ELEIA".
const ELEIA_LOGO_DATAURI = "data:image/png;base64,";
const LOGO_W_PX = 686; // dimensiones del PNG original (para conservar aspecto)
const LOGO_H_PX = 254;

function hasLogo(): boolean {
  return ELEIA_LOGO_DATAURI.startsWith("data:image");
}

interface Meta {
  title: string;
  chip: string;
  dates: string;
}

// ---------------------------------------------------------------- helpers

/** Traduce y arma el detalle de un movimiento (espejo de reportview/reports.py). */
function movDetalle(ev: Dict): string {
  let detalle = String(ev["motivo_bajada"] ?? "");
  if (ev["animales_confirmados"] !== null && ev["animales_confirmados"] !== undefined) {
    const por = String(ev["confirmado_por"] ?? "").trim();
    const extra = por ? `confirmado por ${por}` : "confirmado por el operador";
    detalle = detalle ? `${detalle} · ${extra}` : extra;
  } else if (ev["ambiguo"]) {
    const extra = "peso ambiguo (sin confirmar)";
    detalle = detalle ? `${detalle} · ${extra}` : extra;
  }
  return detalle;
}

// ------------------------------------------------------------ bandas/pie

function drawBandFirst(doc: jsPDF, meta: Meta): void {
  // banda verde a todo el ancho + remate en verde oscuro
  doc.setFillColor(...C.green);
  doc.rect(0, 0, PAGE_W, BAND_FIRST_H, "F");
  doc.setFillColor(...C.greenDark);
  doc.rect(0, BAND_FIRST_H - 1.2, PAGE_W, 1.2, "F");

  // título: producto en bold + nombre del informe al lado
  doc.setTextColor(...C.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(21);
  const yTitle = 12;
  doc.text(BRAND.PRODUCT_NAME, MARGIN, yTitle);
  const tw = doc.getTextWidth(BRAND.PRODUCT_NAME);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(12.5);
  doc.text(`—  ${meta.title}`, MARGIN + tw + 3, yTitle);

  // subtítulo del lockup
  doc.setTextColor(...C.bandText);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  doc.text(`una solución ${BRAND.COMPANY} · ${BRAND.TAGLINE_COMPANY}`, MARGIN, 18.5);

  // chip del lote (píldora verde oscuro) + fechas a su derecha
  const chip = meta.chip || "";
  if (chip) {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    const cw = doc.getTextWidth(chip);
    const chipH = 6.4;
    const chipY = BAND_FIRST_H - 10;
    doc.setFillColor(...C.greenDark);
    doc.roundedRect(MARGIN, chipY, cw + 7.2, chipH, 3.2, 3.2, "F");
    doc.setTextColor(...C.white);
    doc.text(chip, MARGIN + 3.6, chipY + chipH / 2 + 1);
    if (meta.dates) {
      doc.setTextColor(...C.bandText);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8.5);
      doc.text(meta.dates, MARGIN + cw + 11, chipY + chipH / 2 + 1);
    }
  }

  // logo Eleia sobre placa blanca, o wordmark tipográfico
  const right = PAGE_W - MARGIN;
  if (hasLogo()) {
    const plateW = 38;
    const plateH = 15;
    const plateX = right - plateW;
    const plateY = 6;
    doc.setFillColor(...C.white);
    doc.roundedRect(plateX, plateY, plateW, plateH, 1.6, 1.6, "F");
    const imgW = plateW - 4;
    const imgH = imgW * (LOGO_H_PX / LOGO_W_PX);
    const imgY = plateY + (plateH - imgH) / 2;
    try {
      doc.addImage(ELEIA_LOGO_DATAURI, "PNG", plateX + 2, imgY, imgW, imgH, undefined, "FAST");
    } catch {
      /* si el PNG no decodifica, queda la placa blanca */
    }
  } else {
    doc.setTextColor(...C.white);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(15);
    doc.text(BRAND.COMPANY, right, 12, { align: "right" });
    doc.setTextColor(...C.bandText);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.5);
    doc.text(BRAND.TAGLINE_COMPANY, right, 16.5, { align: "right" });
  }
}

function drawBandLater(doc: jsPDF, meta: Meta): void {
  doc.setFillColor(...C.green);
  doc.rect(0, 0, PAGE_W, BAND_LATER_H, "F");
  doc.setFillColor(...C.greenDark);
  doc.rect(0, BAND_LATER_H - 0.8, PAGE_W, 0.8, "F");
  const baseline = BAND_LATER_H / 2 + 1.2;
  doc.setTextColor(...C.white);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.text(BRAND.LOCKUP, MARGIN, baseline);
  doc.setTextColor(...C.bandText);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  const rightTxt = meta.chip ? `${meta.title} · ${meta.chip}` : meta.title;
  doc.text(rightTxt, PAGE_W - MARGIN, baseline, { align: "right" });
}

/** Pasada final: banda por página (portada/slim) + pie "Página X de Y". */
function paintChrome(doc: jsPDF, meta: Meta, footerLeft: string): void {
  const total = doc.getNumberOfPages();
  for (let p = 1; p <= total; p++) {
    doc.setPage(p);
    if (p === 1) drawBandFirst(doc, meta);
    else drawBandLater(doc, meta);
    // pie
    doc.setDrawColor(...C.green);
    doc.setLineWidth(0.4);
    doc.line(MARGIN, PAGE_H - 15.5, PAGE_W - MARGIN, PAGE_H - 15.5);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.5);
    doc.setTextColor(...C.charcoal);
    doc.text(footerLeft, MARGIN, PAGE_H - 11.5);
    doc.text(`Página ${p} de ${total}`, PAGE_W - MARGIN, PAGE_H - 11.5, { align: "right" });
  }
}

// ------------------------------------------------------ bloques de diseño

/** Layout secuencial con salto de página que respeta banda y pie. */
class Layout {
  y = CONTENT_TOP_FIRST;
  constructor(private doc: jsPDF) {}

  /** Asegura `h` mm libres en la página actual; si no caben, salta. */
  ensure(h: number): void {
    if (this.y + h <= CONTENT_BOTTOM) return;
    this.doc.addPage();
    this.y = CONTENT_TOP_LATER;
  }

  section(title: string): void {
    this.ensure(9);
    const barH = 5.2;
    this.doc.setFillColor(...C.green);
    this.doc.rect(MARGIN, this.y, 1.4, barH, "F");
    this.doc.setFont("helvetica", "bold");
    this.doc.setFontSize(10.5);
    this.doc.setTextColor(...C.charcoal);
    this.doc.text(title.toUpperCase(), MARGIN + 3.2, this.y + barH - 1.3);
    this.y += barH + 2;
  }

  /** Tarjetas de totales: rectángulos redondeados + número grande verde. */
  totals(cards: Array<[string, string]>): void {
    const h = 23.5;
    this.ensure(h + 3);
    const gap = 4.2;
    const n = cards.length;
    const cw = (CONTENT_W - gap * (n - 1)) / n;
    cards.forEach(([value, label], i) => {
      const x = MARGIN + i * (cw + gap);
      this.doc.setFillColor(...C.cardBg);
      this.doc.setDrawColor(...C.cardBorder);
      this.doc.setLineWidth(0.3);
      this.doc.roundedRect(x, this.y, cw, h, 2.2, 2.2, "FD");
      // acento superior centrado
      this.doc.setFillColor(...C.green);
      this.doc.rect(x + cw / 2 - 5.5, this.y + 2.2, 11, 0.9, "F");
      // número grande (se encoge si no cabe)
      let size = 19;
      this.doc.setFont("helvetica", "bold");
      this.doc.setFontSize(size);
      while (this.doc.getTextWidth(value) > cw - 5 && size > 9) {
        size -= 0.5;
        this.doc.setFontSize(size);
      }
      this.doc.setTextColor(...C.porci);
      this.doc.text(value, x + cw / 2, this.y + h / 2 + 2, { align: "center" });
      // etiqueta
      this.doc.setFont("helvetica", "bold");
      this.doc.setFontSize(7.2);
      this.doc.setTextColor(...C.charcoal);
      this.doc.text(label, x + cw / 2, this.y + h - 3.5, { align: "center" });
    });
    this.y += h + 3;
  }

  /** Callout "en cristiano" / DEMO: fondo suave + borde izquierdo de color. */
  callout(text: string, accent: RGB = C.green): void {
    this.doc.setFont("helvetica", "normal");
    this.doc.setFontSize(9.5);
    const padX = 3.5;
    const lines = this.doc.splitTextToSize(text, CONTENT_W - 2 * padX - 2) as string[];
    const h = lines.length * 4.6 + 6;
    this.ensure(h + 2);
    this.doc.setFillColor(...C.noteBg);
    this.doc.rect(MARGIN, this.y, CONTENT_W, h, "F");
    this.doc.setFillColor(...accent);
    this.doc.rect(MARGIN, this.y, 1.1, h, "F");
    this.doc.setTextColor(...C.charcoal);
    this.doc.text(lines, MARGIN + padX + 1.5, this.y + 4.6);
    this.y += h + 2;
  }

  /** Tabla (kv o datos) vía autotable; deja `y` en finalY. Las páginas que
   *  cree autotable reservan `top`/`bottom` para banda slim y pie. */
  table(opts: UserOptions): void {
    autoTable(this.doc, {
      ...opts,
      startY: this.y,
      margin: { top: CONTENT_TOP_LATER, bottom: FOOTER_H, left: MARGIN, right: MARGIN },
    });
    const last = (this.doc as unknown as { lastAutoTable?: { finalY: number } }).lastAutoTable;
    this.y = (last?.finalY ?? this.y) + 2;
  }
}

// ------------------------------------------------ estilos de tabla comunes

const KV_STYLES: Partial<UserOptions> = {
  theme: "grid",
  styles: {
    fontSize: 9,
    cellPadding: { top: 1.6, bottom: 1.6, left: 2.4, right: 2.4 },
    textColor: C.charcoal,
    lineColor: C.border,
    lineWidth: 0.1,
    valign: "middle",
  },
  alternateRowStyles: { fillColor: C.zebra },
};

// ============================================================ generador

/**
 * Construye el documento jsPDF del informe de UNA sesión. Devuelve el
 * `doc` para que el llamador decida cómo entregarlo (`.output(...)` para
 * compartir nativo, `.save(...)` para descargar en web).
 */
export function buildReportDoc(
  session: Dict,
  events: Dict[],
  stats: Dict,
  version: string,
): jsPDF {
  const doc = new jsPDF({ unit: "mm", format: "a4", compress: false });

  const loteFull = String(session["lote"] ?? "Sin lote");
  const lote = loteFull.length > 42 ? loteFull.slice(0, 41) + "…" : loteFull;
  const esDemo = Boolean(session["es_demo"]);
  const entrada = fecha(session["hora_entrada"]);
  const salida = fecha(session["hora_salida"]);
  const meta: Meta = {
    title: "Informe de pesaje",
    chip: esDemo ? `DEMO · ${lote}` : lote,
    dates: `Entrada ${entrada}   ·   Salida ${salida}`,
  };

  const L = new Layout(doc);

  // aviso DEMO (ámbar) arriba del todo
  if (esDemo) {
    L.callout(
      "PESAJE DE PRÁCTICA (DEMO) — no es un dato real. Hecho con la báscula " +
        "simulada; no cuenta en las estadísticas y se borra solo una hora " +
        "después de cerrado.",
      C.demo,
    );
  }

  // ------------------------------------------------------ datos del lote
  const modo = String(session["modo"] ?? "lote");
  L.section("Datos del lote");
  L.table({
    ...KV_STYLES,
    body: [
      ["Lote", String(session["lote"] ?? "—")],
      ["Entrada", entrada],
      ["Salida", salida],
      ["Corral de origen", String(session["corral_origen"] ?? "—")],
      ["Destino", String(session["destino"] ?? "—")],
      ["Placa del camión", String(session["placa"] ?? "—")],
      ["Conductor", String(session["conductor"] ?? "—")],
      ["Operador", String(session["operador"] ?? "—")],
      [
        "Modo de pesaje",
        modo === "unidades"
          ? "Por unidades (un cerdo a la vez)"
          : "Por lote (cerdo de prueba + grupos)",
      ],
      ["Estado", cap(String(session["estado"] ?? "—"))],
    ],
    columnStyles: {
      0: { fontStyle: "bold", cellWidth: 52 },
      1: { cellWidth: CONTENT_W - 52 },
    },
  });

  // ------------------------------------------------------------- totales
  const totalKg = Number(session["total_kg"] ?? stats["total_kg"] ?? 0);
  const animalesRaw = session["total_animales"] ?? stats["total_animales"] ?? 0;
  const animales = Math.trunc(Number(animalesRaw));
  const promedioRaw = session["promedio_final"] ?? stats["promedio"];
  const promedio =
    promedioRaw === null || promedioRaw === undefined ? null : Number(promedioRaw);
  L.section("Totales");
  L.totals([
    [String(animales), "CERDOS"],
    [`${fmt(totalKg, 1)} kg`, "PESO TOTAL"],
    [promedio === null ? "—" : `${fmt(promedio, 1)} kg`, "PROMEDIO POR CERDO"],
  ]);

  // ---------------------------------------------------------- estadística
  const tipoMuestra =
    String(stats["tipo_muestra"] ?? "") === "completa"
      ? "Completa (cada cerdo pesado individualmente)"
      : "Estimada (muestra de subidas de a un cerdo)";
  L.section("Estadística del lote");
  L.table({
    ...KV_STYLES,
    body: [
      ["Mediana (kg)", fmt(stats["mediana"], 2)],
      ["Desviación estándar muestral (kg)", fmt(stats["desviacion_std"], 2)],
      ["Varianza muestral (kg²)", fmt(stats["varianza"], 2)],
      ["CV %", fmt(stats["cv_pct"], 2)],
      ["Uniformidad ±10% (%)", fmt(stats["uniformidad_pct"], 2)],
      ["Tipo de muestra", tipoMuestra],
      ["Muestras individuales (n)", fmt(stats["n_muestras"], 0)],
    ],
    columnStyles: {
      0: { fontStyle: "bold", cellWidth: 80 },
      1: { cellWidth: CONTENT_W - 80 },
    },
  });
  L.callout(`En cristiano: ${notaHumana(stats)}`);

  // ---------------------------------------------------------- movimientos
  L.section("Movimientos");
  if (events.length) {
    const rows = events.map((ev) => {
      const n = ev["animales_confirmados"] ?? ev["animales_estimados"];
      return [
        horaMs(ev["ts_ms"]),
        TIPO_HUMANO[String(ev["tipo"])] ?? String(ev["tipo"]),
        `${fmt(ev["delta_kg"], 1)} kg`,
        fmt(n, 0),
        movDetalle(ev),
      ];
    });
    L.table({
      theme: "grid",
      head: [["Hora", "Movimiento", "Peso (kg)", "Animales", "Motivo / detalle"]],
      body: rows,
      styles: {
        fontSize: 8.5,
        cellPadding: { top: 1.8, bottom: 1.8, left: 2.2, right: 2.2 },
        textColor: C.charcoal,
        lineColor: C.border,
        lineWidth: 0.1,
        valign: "middle",
      },
      headStyles: {
        fillColor: C.green,
        textColor: C.white,
        fontStyle: "bold",
        lineColor: C.greenDark,
        lineWidth: 0.1,
      },
      alternateRowStyles: { fillColor: C.zebra },
      columnStyles: {
        0: { cellWidth: 22 },
        1: { cellWidth: 34 },
        2: { cellWidth: 26, halign: "right" },
        3: { cellWidth: 22, halign: "right" },
        4: { cellWidth: CONTENT_W - 104 },
      },
    });
  } else {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9.5);
    doc.setTextColor(...C.charcoal);
    doc.text("Sin movimientos registrados.", MARGIN, L.y + 2);
    L.y += 8;
  }

  // --------------------------------------------------------- conciliación
  if (session["conteo_fisico"] !== null && session["conteo_fisico"] !== undefined) {
    const diff = session["diferencia_conciliacion"];
    L.section("Conciliación");
    L.table({
      ...KV_STYLES,
      body: [
        ["Conteo físico (contado a mano)", fmt(session["conteo_fisico"], 0)],
        ["Conteo de la báscula", fmt(animales, 0)],
        ["Diferencia", fmt(diff, 0)],
      ],
      columnStyles: {
        0: { fontStyle: "bold", cellWidth: 80 },
        1: { cellWidth: CONTENT_W - 80 },
      },
    });
    if (Number(diff) === 0) {
      L.callout("En cristiano: el conteo cuadró perfecto.");
    }
  }

  // -------------------------------------------- bandas + pie (pasada final)
  const generado = new Date().toLocaleString("es");
  const footerLeft = `${BRAND.LOCKUP} · Generado por ${BRAND.PRODUCT_NAME} v${version} · ${generado}`;
  paintChrome(doc, meta, footerLeft);
  return doc;
}

/**
 * Bytes del PDF del informe (para compartir/guardar como archivo nativo).
 * `%PDF` al inicio; sin compresión para streams estables.
 */
export function reportPdfBytes(
  session: Dict,
  events: Dict[],
  stats: Dict,
  version: string,
): Uint8Array {
  const doc = buildReportDoc(session, events, stats, version);
  return new Uint8Array(doc.output("arraybuffer"));
}
